content.css:
.info-container {
  height: 100%;
}
.info-message {
  vertical-align: middle;
  position: relative;
  top: 50%;
  transform: translateY(-50%);
  text-align: center;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 14px;
  padding: 10px;
}
.loader {
  border: 5px solid #d5d6d8;
  border-radius: 50%;
  border-top: 5px solid #555;
  width: 20px;
  height: 20px;
  display: inline-block;
  -webkit-animation: spin 1s linear infinite;
  animation: spin 1s linear infinite;
}
/* Safari */
@-webkit-keyframes spin {
  0% {
    -webkit-transform: rotate(0deg);
  }
  100% {
    -webkit-transform: rotate(360deg);
  }
}
@keyframes spin {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
.error-indicator {
  width: 35px;
  height: 35px;
  display: inline-block;
}
.vbi-logo {
  width: 35vh;
  height: 13vh;
  max-width: 93px;
  max-height: 30px;
}
.vbi-logo-gray {
  background-image: url('data:image/png;base64,');
}
.vbi-logo-color {
  background-image: url('data:image/png;base64,');
}
.background-image {
  background-repeat: no-repeat;
  background-size: contain;
}
.editor-icon {
  top: 0px !important;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  margin-bottom: 10px;
  background-color: #f2c811;
  box-shadow: 0 4px 8px 0 rgba(0, 0, 0, 0.2), 0 6px 20px 0 rgba(0, 0, 0, 0.19);
}
.editor-icon:hover {
  box-shadow: 0 4px 8px 0 rgba(0, 0, 0, 0.14), 0 6px 20px 0 rgba(251, 251, 251, 0.89);
}
.editor-icon img {
  border-style: none;
  width: 17px;
  position: relative;
  top: 11px;
  left: 11px;
}
.close-icon .edit-icon-img {
  display: none !important;
}
.edit-icon .close-icon-img {
  display: none !important;
}
.modal-close-button {
  height: 13px;
  width: 12px;
  right: 4px;
  position: absolute;
  top: 2px;
  z-index: 60;
}
.close-icon-2 {
  background-image: url('data:image/png;base64,');
}
.close-icon-2:hover {
  background-image: url('data:image/png;base64,');
}
.vbi-info-icon {
  width: 40px;
  height: 40px;
  margin: 0 auto;
  background-color: rgba(255, 255, 255, 0.75);
  background-image: url("data:image/svg+xml;base64,");
}
.vbi-info-icon.edit-mode {
  background-image: url("data:image/svg+xml;base64,");
}
.resize-chart {
  height: calc(100% - 40px) !important;
}
.vbi-smoke-screen .modal-close-button {
  display: none !important;
}
.vbi-license-alert-icon {
  width: 16px;
  height: 16px;
  position: absolute;
  margin: 0 auto;
  right: 15px;
  background-image: url('data:image/png;base64,');
}
.vbi-license-alert-icon:hover {
  background-image: url('data:image/png;base64,');
}
.vbi-info-icon:hover {
  background-image: url("data:image/svg+xml;base64,");
  opacity: 0.5;
}
.vbi-info-icon.edit-mode:hover {
  background-image: url("data:image/svg+xml;base64,");
  opacity: 1;
}
@media (max-width: 231px), (max-height: 151px) {
  .vbi-logo {
    width: 40px;
    height: 15px;
  }
  .vbi-logo-gray {
    width: 40px;
    height: 15px;
    background-image: url('data:image/png;base64,');
  }
}
@media screen and (max-height: 245px) {
  .vbi-license-modal {
    height: 150px !important;
  }
}
.vbi-smoke-screen .vbi-logo-color {
  background-image: url('data:image/svg+xml;base64,');
}
.vbi-error-url a {
  text-decoration: underline;
  color: #f2c811;
}
.vbi-smoke-screen .vbi-error-url a {
  color: blue;
}
.right-bottom-ps {
  position: absolute;
  bottom: 4px;
  right: 4px;
}
.right-top-ps {
  position: absolute;
  z-index: 10;
  top: 4px;
  right: 4px;
}
.vbi-smoke-screen {
  width: 100%;
  bottom: 0;
  position: absolute;
  background: rgba(250, 250, 250, 0.1);
  z-index: 999;
}
.vbi-smoke-screen .error-span {
  font-size: 20px;
}
.resize-chart {
  width: calc(100% - 400px);
  left: 400px;
}
.remove-resize-chart {
  width: 100% !important;
  left: 0% !important;
}
.infiniteBottom {
  top: 1000000px !important;
}
.plot-area {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0%;
}
.editor--show {
  display: block;
}
.vbi-kpi-tile .kpi-label {
  font-size: 15vh;
  font-weight: 100;
  color: #888484;
}
.vbi-kpi-tile .kpi-value {
  font-size: 20vh;
}
.vbi-show-landing-page {
  width: 100%;
  height: 100%;
  min-width: 500px;
  min-height: 400px;
  vertical-align: middle;
  position: relative;
  top: 30%;
  transform: translateY(-30%);
  text-align: center;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 25px;
  padding: 10px;
}
.vbi-landing-message {
  position: relative;
  top: 40%;
  transform: translateY(-50%);
}
.vbi-title-span {
  height: 10%;
  font-weight: bold;
  font-size: 35px;
}
.vbi-info-url {
  padding: 10px;
}
.vbi-info-url a {
  text-decoration: underline;
  color: #010080;
}
.vbi-logo-div {
  background-image: url('data:image/png;base64,');
  background-position: center;
  margin: auto;
  height: 60px;
  width: 180px;
}
.pro-used-msg,
.buy-licence,
.renew-licence,
.licence-expired-msg,
.no-licence-msg,
.thanks-msg,
.invalid-licence-msg {
  display: none;
}
.invalid-licence .invalid-licence-msg,
.invalid-licence .buy-licence {
  display: block !important;
}
.pro-user .thanks-msg {
  display: block !important;
}
.no-licence .no-licence-msg,
.no-licence .buy-licence {
  display: block !important;
}
.no-license-pro-used .pro-used-msg,
.no-license-pro-used .buy-licence {
  display: block !important;
}
.licence-expired .licence-expired-msg,
.licence-expired .renew-licence {
  display: block !important;
}
.vbi-licence-modal {
  background: #fff;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.3);
  align-items: center;
  color: black;
  font-family: 'Segoe UI', wf_segoe-ui_normal, helvetica, arial, sans-serif;
  top: 42px;
  right: 4px;
  position: absolute;
}
.vbi-licence-modal.pro-user {
  max-height: 220px !important;
}
.vbi-licence-modal.licence-expired {
  max-height: 240px !important;
}
.vbi-licence-modal.editor-icon-present {
  z-index: 99;
}
@media only screen and (max-width: 600px) {
  .vbi-licence-body-item,
  .footer-item {
    width: 100% !important;
  }
  .copy-rights {
    text-align: left !important;
    padding-left: 0px !important;
  }
  .warning-message {
    padding-top: 10px;
  }
  .vbi-licence-modal {
    max-height: 425px !important;
  }
  .vbi-licence-modal.pro-user {
    max-height: 290px !important;
  }
  .vbi-licence-modal.licence-expired {
    max-height: 370px !important;
  }
}
.vbi-licence-modal-item {
  width: 100%;
}
.version-info {
  cursor: pointer;
}
.vbi-logo-licence {
  cursor: pointer;
}
.version-info:hover,
.buy-licence a:hover {
  color: #f2c811 !important;
}
.vbi-logo-licence img {
  height: 25px;
}
.vbi-licence-header {
  display: flex;
  padding-bottom: 7px;
  justify-content: space-between;
  border-bottom: 1px solid #efefef;
  align-items: center;
}
.vbi-licence-modal .chart-name {
  padding: 0px 5px;
  font-weight: 600;
  height: 100%;
}
.vbi-licence-modal .vbi-licence-body {
  padding: 5px;
}
.vbi-licence-modal .info-message-licence {
  width: 50%;
  font-size: 12px;
  padding: 0px 10px;
  box-sizing: border-box;
}
.vbi-licence-modal .info-menu {
  width: 50%;
  padding: 0px 10px;
  box-sizing: border-box;
}
.vbi-licence-modal .menu-item {
  text-transform: uppercase;
  font-weight: 500;
  font-size: 13px;
  padding-bottom: 2px;
  color: #616161;
  cursor: pointer;
}
.vbi-licence-modal .footer a:hover,
.vbi-licence-modal .menu-item:hover {
  color: #f2c811;
}
.vbi-licence-modal .footer {
  border-top: 1px solid #efefef;
  font-size: 12px;
  padding-left: 5px;
  padding-top: 5px;
  color: gray;
  display: flex;
  justify-content: space-between;
  padding-bottom: 10px;
}
.vbi-licence-modal .copy-rights {
  text-align: right;
  width: 30%;
  padding: 0px 5px;
}
.vbi-licence-modal .feedback-link {
  width: 70%;
}
.free-trial-btn {
  margin-top: 5px;
  padding: 8px 8px;
  text-transform: uppercase;
  font-weight: 500;
  text-align: center;
  background: linear-gradient(to right, #eaeaea 50%, #f2c811 50%);
  background-size: 200% 100%;
  background-position: left bottom;
  transition: all 2s ease;
  cursor: pointer;
}
.free-trial-btn:hover {
  background-position: right bottom;
}
.buy-licence {
  padding-top: 5px;
}
.vbi-licence-modal .email-ui input {
  border: 1px solid #efefef;
  width: 100%;
  margin-top: 5px;
  box-sizing: border-box;
  padding: 6px;
}
.flex-container {
  display: flex;
  flex-direction: column;
}
.help-modal::-webkit-scrollbar {
  width: 8px;
}
.help-modal::-webkit-scrollbar-track {
  background-color: #e2e0e0;
}
.help-modal::-webkit-scrollbar-thumb {
  border-radius: 10px;
  background-color: #a0a0a0;
}
.edit-mode .vbi-info-icon {
  top: 46px;
  right: 12px;
}
/*help modal*/
.help-modal {
  background-color: #ffffff;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  box-shadow: 0 0 20px #bbb;
  width: 430px;
  height: 170px;
  right: 0;
  top: 150px;
  display: none;
  padding: 16px 16px 4px 16px;
  color: #333333;
  box-sizing: border-box;
}
.help-modal .header {
  text-align: center;
}
.help-modal-logo {
  width: 70px;
  height: 24px;
}
.xviz-icon-full {
  background-repeat: no-repeat;
  background-size: cover;
  background-image: url('data:image/svg+xml;base64,');
}
.help-modal h3 {
  font-size: 18px;
  font-weight: 400 !important;
  padding-left: 15px;
  margin: 0;
}
.ratings {
  display: inline;
}
.help-modal .close-modal {
  position: absolute;
  right: 16px;
  top: 16px;
  cursor: pointer;
  font-size: 14px;
  width: 20px;
  height: 20px;
  background-image: url('data:image/svg+xml;base64,');
}
.section {
  float: left;
  width: 33.33%;
}
.section .section-label {
  font-size: 14px;
  line-height: 14px;
  text-transform: uppercase !important;
  font-weight: 500 !important;
}
.help-link {
  display: block;
  font-size: 12px;
  text-decoration: none;
  box-shadow: none !important;
  color: #333333;
  line-height: 24px;
}
.licence-section {
  font-size: 12px;
  box-shadow: none !important;
  color: #333333;
}
.modal-footer {
  border-top: 1px solid #eaeaea;
  margin-top: 14px;
}
.modal-footer > p {
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  font-weight: 400 !important;
  display: inline-block;
  width: 50%;
}
.copyright {
  text-align: right;
}
.bold {
  font-weight: bold;
}
.vbi-licence-body,
.modal-footer {
  float: left;
  width: 100%;
}
.help-modal {
  float: left;
}
@media (max-width: 480px) {
  .help-modal {
    width: 100%;
    overflow-x: auto;
  }
  .section,
  .modal-footer > p {
    width: 100%;
  }
  .modal-footer > p {
    margin-bottom: 0;
  }
  .modal-footer .copyright {
    text-align: left;
  }
}
@media (max-height: 230px) {
  .help-modal {
    overflow-y: scroll !important;
    height: 75px !important;
  }
}
@media (max-width: 230px) {
  .help-modal {
    width: 150px !important;
  }
  .vbi-licence-modal .vbi-licence-body p {
    font-size: 10px !important;
  }
}
/*Info & Edit Iocn Positions*/
.vbi-info-icon {
  position: absolute;
  /* top: -7px; */
  top: -3px;
  right: 3px;
  width: 30px;
  height: 30px;
}
@media (max-width: 231px), (max-height: 151px) {
  .vbi-info-icon {
    width: 15px;
    height: 15px;
    right: 0px;
    margin: 4px !important;
  }
}
.editor-icon {
  position: absolute;
  right: 0;
  top: 35px !important;
}
.vbi-display-data-icon img {
  width: 30px !important;
}
.vbi-display-data-icon {
  width: 27px !important;
  height: 30px !important;
  top: -2px !important;
  right: 47px !important;
}
.highcharts-button-hover rect,
.highcharts-button-pressed {
  fill: #ffffff !important;
  stroke: #ffffff !important;
}
/*Datalabel Background*/
.highcharts-series-inactive {
  opacity: 1 !important;
}
.highcharts-data-label tspan {
  stroke-width: 0px !important;
}


